 updatePosts(){for(const [id,post] of Object.entries(this.world.post)){if(!post.cleared&&this.npcs.filter(n=>n.poi===id).every(n=>n.hp<=0)){post.cleared=true;post.clearDay=this.day;this.mark('post_clear');this.emit('notice',{line:POI[id].name+' is quiet. It will stay quiet until dawn.'});if(['s2','s3'].includes(id)&&!this.world.safehouses.includes(id))this.world.safehouses.push(id);}if(post.reinforce){const r=post.reinforce,dest=POI[id],theta=Math.atan2(dest.x-r.x,dest.z-r.z);r.x+=Math.sin(theta)*4.5;r.z+=Math.cos(theta)*4.5;r.eta-=.25;if(r.eta<=0||dist(r,dest)<12){for(let i=0;i<Math.ceil(post.strength*.6);i++)this.spawnNPC(dest,post.owner,i);post.cleared=false;post.reinforce=null;this.mark('post_regarrison');}}}}
 updateContract(){const c=this.contract,s=this.objective();if(!c||!s||c.failed)return;const place=s.npc==='driver'?this.vehicles.find(v=>v.tag==='radio_truck'):POI[s.poi],d=dist(this.p,place);if(s.tags?.includes('radio_truck')||s.npc==='driver'){const truck=this.vehicles.find(v=>v.tag==='radio_truck');this.p.waypoint={x:truck.x,z:truck.z};if(s.npc==='driver'&&truck.health<=0){this.nextStep();return;}}if(['goto','escort','deliver','drive_cargo'].includes(s.do)&&d<(s.r||30)&&(s.do!=='escort'||!this.world.flags.escortTruck||dist(this.vehicles.find(v=>v.id===this.world.flags.escortTruck),place)<(s.r||30))&&(s.do!=='drive_cargo'||this.vehicles.find(v=>v.id===this.p.vehicle)?.kind==='cargo')){this.nextStep();return;}if(s.do==='kill'&&this.npcs.filter(n=>n.poi===s.poi&&n.hp>0).length===0){this.nextStep();return;}if(s.do==='destroy'&&(s.tags||[]).every(id=>id==='radio_truck'?this.vehicles.find(v=>v.tag===id)?.health<80:this.entities.find(e=>e.id===id)?.dead)){this.nextStep();return;}if(s.do==='wait_event'){if(!this.train.active&&!this.train.passed){this.train.active=true;this.train.x=-100;}if(this.elapsed-(c.stepAt||0)>(s.duration||10)||this.train.x>445)this.nextStep();}if(s.do==='survive'||s.do==='hold_zone'){if(d<100)c.progress+=.25;if(c.progress>=(s.duration||10)){if(s.mercy&&!this.world.flags.mercyC7){this.world.flags.mercyC7=true;this.downBuddy();}if(!this.mercy)this.nextStep();}}if(s.do==='choice'&&!this.pendingChoice){this.pendingChoice=s.choices;this.emit('choice',{choices:s.choices});}if(s.do==='ending')this.updateEnding(.25);}
